#数据导入from sklearn.datasets import load_digitsdigits = load_digits()labels = digits.targetimages = digits.images#像素可视化import matplotlib.pyplot as pltindex = 7image = images[index]plt.imshow( #负责把数组画成图像    image,    cmap="gray", #用灰度显示数值    vmin = 0,    #固定显示范围    vmax = 16,   #固定显示范围    interpolation="nearest" #放大显示时 保留清晰的像素方块)plt.title(f"label:{labels[index]}")plt.show()#把每张8*8图片展开成64个数x = images.reshape(len(images),64)x = x/16.0y = labelsfrom sklearn.model_selection import train_test_split#第一次划分，留出20%作为测试集x_pool,x_test,y_pool,y_test = train_test_split(    x,    y,    test_size=0.2,    random_state=42,    stratify=y)#第二次划分，从剩余数据中取出25%作为验证集x_train,x_val,y_train,y_val = train_test_split(    x_pool,    y_pool,    test_size=0.25,    random_state=42,    stratify=y_pool)# print("训练集：", x_train.shape, y_train.shape)# print("验证集：", x_val.shape, y_val.shape)# print("测试集：", x_test.shape, y_test.shape)#选择三候选模型 用验证机决定保留哪个from sklearn.linear_model import LogisticRegressionfrom sklearn.metrics import accuracy_score#记录当前最好的模型best_model = Nonebest_val_acc = -1.0best_C = Nonefor C in [0.1,1.0,10.0]:    #1.创建一个尚未训练的模型    model = LogisticRegression(        C = C ,        solver = "lbfgs",        max_iter=1000    )    # 2.训练：用训练图片和标签学习参数    model.fit(x_train, y_train)    # 3.分别预测训练集与验证集    train_pred = model.predict(x_train)    val_pred = model.predict(x_val)    # 4.把预测值和真值进行比较    train_acc = accuracy_score(y_train, train_pred)    val_acc = accuracy_score(y_val, val_pred)    # print(    #     f"C={C:4.1f} | "    #     f"训练准确率={train_acc:.2%} | "    #     f"验证准确率={val_acc:.2%}"    # )    # 验证准确率更高，就保留当前模型    if val_acc > best_val_acc:        best_val_acc = val_acc        best_C = C        best_model = model# print(f"最终选择：C={best_C}")## print(f"最佳验证准确率：{best_val_acc:.2%}")test_pred = best_model.predict(x_test)test_acc = accuracy_score(y_test, test_pred)correct = (test_pred == y_test).sum()print(f"最终测试准确率：{test_acc:.2%}")print(f"预测正确：{correct} / {len(y_test)}")print(f"预测错误：{len(y_test) - correct}")